Lemma qcw_lit1 : forall len, 1 <= len <= 64 ->
  Z.land (bv_unsigned (Z_to_bv 64 (2147450880 + bv_unsigned (Z_to_bv 64 (188276 + len + -1)) ≫ 3))) 18446744073709551608
  = if len <=? 12 then 2147474408 else 2147474416.
Proof.
  intros len Hl.
  assert (Hc : forall n : nat, (n < 64)%nat ->
    Z.land (bv_unsigned (Z_to_bv 64 (2147450880 + bv_unsigned (Z_to_bv 64 (188276 + (Z.of_nat n + 1) + -1)) ≫ 3))) 18446744073709551608
    = if Z.of_nat n + 1 <=? 12 then 2147474408 else 2147474416).
  { intros n Hn. do 64 (destruct n as [|n]; [vm_compute; reflexivity|]). lia. }
  specialize (Hc (Z.to_nat (len - 1)) ltac:(lia)).
  rewrite Z2Nat.id in Hc by lia.
  replace (len - 1 + 1) with len in Hc by lia.
  exact Hc.
Qed.

